"""Writes tests/fixtures/sections_golden.json: synthetic listener-fly spike counts and per-bar energy for one track,
two section-model specs in the brains/sections_*.json format (v3: learned arrangement + energy features; v2: the
hand-set arrangement, neuron features only), and the posteriors flybrain/sections.py gives for them.

tests/test_sections.py checks the Python side still gives these numbers; tools/test_sections_parity.mjs checks the
browser's re-implementation (web/js/sections.js) does too. Regenerate only when the model is meant to change:

    python tests/fixtures/make_sections_golden.py
"""
from __future__ import annotations

import json
import sys
from pathlib import Path

import numpy as np

HERE = Path(__file__).resolve().parent
sys.path.insert(0, str(HERE.parent.parent))
from flybrain import sections as S  # noqa: E402

OUT = HERE / "sections_golden.json"
N_BARS = 40
BPM = 128.0
BAR_S = 4 * 60 / BPM


def track(rng):
    """Output neurons (slots) of 4 cell types, their spike counts per bar (a track with an intro, two mains around a
    break, an outro), and the per-bar energy that goes with it."""
    outputs = [{"cls": c, "type": t} for c, t in [("descending", "DNa"), ("descending", "DNa"), ("descending", "DNb"),
                                                  ("descending", "DNb"), ("descending", "DNb"), ("motor", "MN1"),
                                                  ("motor", "MN2"), ("motor", "MN2")]]
    shape = np.array([0.2] * 8 + [1.0] * 12 + [0.4] * 6 + [1.0] * 10 + [0.25] * 4)
    base = rng.uniform(2, 12, len(outputs))
    gain = rng.uniform(-0.5, 1.5, len(outputs))
    rate = base[None, :] * np.exp(gain[None, :] * (shape[:, None] - 0.6))      # Hz per slot per bar
    counts = rng.poisson(rate * BAR_S)
    energy = shape * rng.uniform(0.8, 1.2, N_BARS) * 0.05
    return outputs, counts, energy


def spec_v3(rng, groups, outputs_labels):
    k = len(S.DJ_CLASSES)
    T, start, pos = S.learn_arrangement(outputs_labels, k)
    d = 2 * len(groups) + 2
    return {"version": 3, "classes": S.DJ_CLASSES, "groups": groups, "energy": True,
            "feature": {"sd_floor": 0.05, "warmup_bars": 4, "context_bars": 4},
            "W": np.round(rng.normal(0, 0.8, (d, k)), 5).tolist(), "b": np.round(rng.normal(0, 0.3, k), 5).tolist(),
            "T": np.round(T, 5).tolist(), "start": np.round(start, 5).tolist(), "pos": np.round(pos, 4).tolist()}


def spec_v2(rng, groups):
    k = len(S.CLASSES)
    d = 2 * len(groups)
    return {"version": 2, "classes": S.CLASSES, "groups": groups, "energy": False,
            "feature": {"sd_floor": 0.05, "warmup_bars": 4, "context_bars": 4},
            "W": np.round(rng.normal(0, 0.8, (d, k)), 5).tolist(), "b": np.round(rng.normal(0, 0.3, k), 5).tolist()}


def posteriors(spec, outputs, counts, energy, frac):
    """What the trained model gives for this track, from flybrain/sections.py (the training-side code)."""
    groups, group_of = S.type_groups(outputs)
    assert groups == spec["groups"]
    X = S.bar_features(counts / BAR_S, group_of, len(groups))
    if spec["energy"]:
        X = np.concatenate([X, S.energy_features(energy)], 1)
    P = S.softmax(X @ np.array(spec["W"]) + np.array(spec["b"]))
    if "T" in spec:
        A = S.hmm_filter(P, frac, T=np.array(spec["T"]), start=np.array(spec["start"]), pos=np.array(spec["pos"]))
    else:
        A = S.hmm_filter(P, frac)
    return P, A


def build():
    rng = np.random.default_rng(20261009)
    outputs, counts, energy = track(rng)
    groups, _ = S.type_groups(outputs)
    frac = (np.arange(N_BARS) + 0.5) / N_BARS            # the training side's track position: each bar's midpoint
    labels = [rng.integers(0, len(S.DJ_CLASSES), 30) for _ in range(6)]
    cases = {}
    for name, spec in (("v3_fused", spec_v3(rng, groups, [np.sort(y) for y in labels])), ("v2_fly", spec_v2(rng, groups))):
        P, A = posteriors(spec, outputs, counts, energy, frac)
        cases[name] = {"spec": spec, "P": P.tolist(), "posterior": A.tolist()}
    return {"about": "generated by tests/fixtures/make_sections_golden.py; see its docstring",
            "bpm": BPM, "bar_s": BAR_S, "outputs": outputs, "counts": counts.tolist(), "energy": energy.tolist(),
            "frac": frac.tolist(), "cases": cases}


if __name__ == "__main__":
    OUT.write_text(json.dumps(build(), indent=None, separators=(",", ":")) + "\n")
    print("wrote", OUT)
